code_sketch:
final case class Money(amount: BigDecimal, currency: Currency):
  require(amount.scale <= 2, "Money is exact to 2 decimals")
  def +(other: Money): Money = copy(amount = amount + other.amount)

object Money:
  private def normalise(code: String): String = code.toUpperCase   // bounded to the companion
  def of(amount: BigDecimal, code: String): Money = Money(amount, Currency(normalise(code)))

